import { readdir, readFile, writeFile } from "node:fs/promises";
import { extname, join } from "node:path";

export const generatedWarningHtml =
  "<!-- Generated from canonical repository sources. Do not edit this file directly. -->";
export const generatedWarningMdx =
  "{/* Generated from canonical repository sources. Do not edit this file directly. */}";

export function normalizeGeneratedMarkdown(markdown) {
  const normalized = markdown.replace(generatedWarningHtml, generatedWarningMdx);

  if (!normalized.includes(generatedWarningMdx)) {
    throw new Error("Generated documentation page is missing its source warning.");
  }

  return normalized;
}

export async function normalizeGeneratedDocumentation(directory) {
  let normalizedPages = 0;

  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const absolutePath = join(directory, entry.name);

    if (entry.isDirectory()) {
      normalizedPages += await normalizeGeneratedDocumentation(absolutePath);
      continue;
    }

    if (!entry.isFile() || ![".md", ".mdx"].includes(extname(entry.name))) {
      continue;
    }

    const original = await readFile(absolutePath, "utf8");
    const normalized = normalizeGeneratedMarkdown(original);

    if (normalized !== original) {
      await writeFile(absolutePath, normalized, "utf8");
    }
    normalizedPages += 1;
  }

  return normalizedPages;
}
